using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidNativeTestHandoffFileStore{private readonly string _path;public AndroidNativeTestHandoffFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(AndroidNativeTestHandoff value){if(value.RequiredScenarios.Count==0)throw new InvalidOperationException("Android test handoff requires scenarios.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public AndroidNativeTestHandoff Load()=>JsonSerializer.Deserialize<AndroidNativeTestHandoff>(File.ReadAllText(_path))??throw new InvalidOperationException("Android native test handoff JSON is invalid.");}
